    # The multicolor frames are canvases; fully decorated frames of the same
    # dimensions provide the interior raster. A hollow frame is filled by the
    # pattern with identical inner dimensions, recolored in its own color.
    from collections import defaultdict
    points=defaultdict(list)
    for r,row in enumerate(grid):
        for c,value in enumerate(row):
            if value:
                points[value].append((r,c))
    boxes={}
    for color,cells in points.items():
        boxes[color]=(min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells))
    out=[row[:] for row in grid]
    sources=[]
    for color,(r0,r1,c0,c1) in boxes.items():
        height,width=r1-r0-1,c1-c0-1
        if height<=0 or width<=0:
            continue
        pattern=[(r-r0-1,c-c0-1) for r,c in points[color] if r0<r<r1 and c0<c<c1]
        if pattern:
            sources.append((color,height,width,pattern))
    for destination,(r0,r1,c0,c1) in boxes.items():
        height,width=r1-r0-1,c1-c0-1
        if height<=0 or width<=0:
            continue
        if any(r0<r<r1 and c0<c<c1 for r,c in points[destination]):
            continue
        candidates=[(color,pattern) for color,sh,sw,pattern in sources
                    if color!=destination and (sh,sw)==(height,width)]
        if not candidates:
            continue
        _,pattern=candidates[0]
        for dr,dc in pattern:
            out[r0+1+dr][c0+1+dc]=destination
    return out

def _verification():
