    for color,cells in points.items():
        boxes[color]=(min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells))
    out=[row[:] for row in grid]
    frames=[]
    for color,(r0,r1,c0,c1) in boxes.items():
        ih,iw=r1-r0-1,c1-c0-1
        if ih<=0 or iw<=0:
            continue
        pattern={(r-r0-1,c-c0-1) for r,c in points[color] if r0<r<r1 and c0<c<c1}
        frames.append((color,ih,iw,pattern))
    for color,(r0,r1,c0,c1) in boxes.items():
        ih,iw=r1-r0-1,c1-c0-1
        if ih<=0 or iw<=0:
            continue
        own={(r-r0-1,c-c0-1) for r,c in points[color] if r0<r<r1 and c0<c<c1}
