 "content": "def transform(grid):
    # Each object is an outlined square/rectangle. The two irregular filled
    # examples in demos show the pattern that must be replicated to empty frames
    # of the same dimensions. Here the designed 7-frame's raster is used in
    # the corresponding empty 5/8/1/6/3 frames, aligned top-left in the interior.
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                cells[v].append((r,c))
    bounds={}
    for v,ps in cells.items():
        bounds[v]=(min(r for r,c in ps),max(r for r,c in ps),min(c for r,c in ps),max(c for r,c in ps))
    result=[row[:] for row in grid]
    # A noisy interior design is recognizable as the only object with interior
    # cells beyond its bounding outline. Transfer it to hollow frames, resizing.
    sources=[]
    for color,(r0,r1,c0,c1) in bounds.items():
        ih,iw=r1-r0-1,c1-c0-1
        if ih<=0 or iw<=0:
            continue
        design=[(r-r0-1,c-c0-1) for r,c in cells[color] if r0<r<r1 and c0<c<c1]
        if design:
            sources.append((color,ih,iw,design))
    # Pick the most complex source raster; in examples it is the irregular full design.
    if not sources:
        return result
    src,sh,sw,design=max(sources,key=lambda s:len(s[3]))
    for color,(r0,r1,c0,c1) in bounds.items():
        if color==src:
            continue
        ih,iw=r1-r0-1,c1-c0-1
        if ih<=0 or iw<=0:
            continue
        # Leave any frame already containing internal design unchanged.
        if any(r0<r<r1 and c0<c<c1 for r,c in cells[color]):
            continue
        # Replicate the raster, scaling normalized coordinates to the target interior.
        for pr,pc in design:
            rr=r0+1+round(pr*max(0,ih-1)/max(1,sh-1))
            cc=c0+1+round(pc*max(0,iw-1)/max(1,sw-1))
            result[rr][cc]=color
    return result
