    # Pattern copying is defined by shared frame dimensions. The demonstrations
    # indicate the interior raster is copied from an art-filled frame to its
    # matching empty frame and recolored with the recipient frame color.
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(grid):
        for c,value in enumerate(row):
            if value:
                cells[value].append((r,c))
    frames={}
    for color,ps in cells.items():
        r0=min(r for r,c in ps); r1=max(r for r,c in ps)
        c0=min(c for r,c in ps); c1=max(c for r,c in ps)
        if r1-r0>=2 and c1-c0>=2:
            interior={(r-r0-1,c-c0-1) for r,c in ps
                      if r0<r<r1 and c0<c<c1}
            frames[color]=(r0,r1,c0,c1,interior)
    out=[row[:] for row in grid]
    for dst,(r0,r1,c0,c1,own) in frames.items():
        if own:
            continue
        h,w=r1-r0-1,c1-c0-1
        # Retrieve a like-shaped interior pattern from an art-filled frame.
        srcs=[]
        for src,(a,b,x,y,pattern) in frames.items():
            if src==dst or not pattern:
                continue
            if (b-a-1,y-x-1)==(h,w):
                srcs.append((src,pattern))
        if not srcs:
            continue
        _,pattern=srcs[0]
